import subprocess, os, tempfile, time
ORIG="/workspace/executable"
def mkd(files):
    d=tempfile.mkdtemp(prefix="nt_", dir="/tmp")
    for k,v in (files or {}).items():
        p=os.path.join(d,k); os.makedirs(os.path.dirname(p) or d,exist_ok=True)
        with open(p,'wb' if isinstance(v,bytes) else 'w') as f: f.write(v)
    return d
def run_in(d,args,env=None):
    e=os.environ.copy()
