    for comp in path.split('/'):
        if comp == "" or comp == ".":
            continue
        elif comp == "..":
            if parts and parts[-1] != "..":
                parts.pop()
            elif not is_abs:
                parts.append("..")
            # absolute: discard
        else:
            parts.append(comp)
    result = ('/' if is_abs else '') + '/'.join(parts)
    if result == "":
        result = '/' if is_abs else '.'
    return result

