    try:
        return os.strerror(e)
    except Exception:
        return str(e)

def shell_escape(s):
    if s == "":
        return "''"
    ok = True
    for ch in s:
        if ('A' <= ch <= 'Z') or ('a' <= ch <= 'z') or ('0' <= ch <= '9') or ch in '+-./_':
            continue
