    # Ninja's EditDistance allows swapping? We implement standard DP with substitution.
    la, lb = len(a), len(b)
    if la == 0:
        return lb
    if lb == 0:
        return la
    prev = list(range(lb+1))
    for i in range(1, la+1):
        cur = [i] + [0]*lb
        ca = a[i-1]
        for j in range(1, lb+1):
            cost = 0 if ca == b[j-1] else 1
            cur[j] = min(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
        prev = cur
    return prev[lb]

