    # Use: suggestion if best_dist <= len(best)  (for ''->in, 2<=2 yes; xyz->foo.o? xyz to in maybe 3 >2 no; xyz to output 6 >)
    # Also if word long, allow up to ... 
    if best_dist is not None and best_dist <= max(2, len(best)):
