        return st.st_mtime_ns, True
    except FileNotFoundError:
        return 0, False
    except NotADirectoryError:
        return 0, False
    except OSError:
        return 0, False

def guess_parallelism():
    procs = 0
    try:
        procs = len(os.sched_getaffinity(0))
    except Exception:
        procs = os.cpu_count() or 0
    # cgroup v2 cpu.max
    limit = None
    try:
        # find cgroup path
        cg_path = None
        try:
            with open('/proc/self/cgroup') as f:
                for line in f:
                    parts = line.strip().split(':')
                    if len(parts) >= 3 and (parts[1] == '' or 'cpu' in parts[1].split(',')):
                        cg_path = parts[2]
                        break
        except Exception:
            pass
        candidates = []
        if cg_path:
            candidates.append('/sys/fs/cgroup' + cg_path + '/cpu.max')
            # walk up
            p = cg_path
            while p and p != '/':
                p = os.path.dirname(p)
                candidates.append('/sys/fs/cgroup' + p + '/cpu.max')
        candidates.append('/sys/fs/cgroup/cpu.max')
        for cand in candidates:
            try:
                with open(cand) as f:
                    content = f.read().strip().split()
                if len(content) >= 2 and content[0].lower() != 'max':
                    quota = int(content[0]); period = int(content[1])
                    if quota > 0 and period > 0:
                        limit = (quota + period - 1)//period
                        break
            except Exception:
                continue
        if limit is None:
            # v1
            for cand_quota in ['/sys/fs/cgroup/cpu/cpu.cfs_quota_us']:
                try:
                    quota = int(open(cand_quota).read().strip())
                    period = int(open('/sys/fs/cgroup/cpu/cpu.cfs_period_us').read().strip())
                    if quota > 0 and period > 0:
                        limit = (quota + period - 1)//period
                    break
                except Exception:
                    pass
    except Exception:
        pass
    cores = procs
    if limit is not None and limit > 0:
        cores = min(cores, limit) if cores else limit
    if cores and cores > 0:
        return cores + 2
    return 4

# EvalString
class EvalString:
    __slots__ = ('parts',)
    def __init__(self, parts=None):
        self.parts = parts if parts is not None else []  # list of (is_var, text)
    def evaluate(self, lookup):
        out = []
        for is_var, txt in self.parts:
            if is_var:
                out.append(lookup(txt))
            else:
                out.append(txt)
        return ''.join(out)
    def __str__(self):
        # Reconstruction used by rules -d : variables as ${name}
        out = []
        for is_var, txt in self.parts:
            if is_var:
                out.append('${' + txt + '}')
            else:
                out.append(txt)
        return ''.join(out)
    def raw(self):
        return str(self)

class ParseErrorInfo(Exception):
    def __init__(self, filename, line, message, line_text=None, caret=None):
        super().__init__(message)
