                    if n in edge.order_only_inputs: edge.order_only_inputs.remove(n)
                    n.phony_self_loop=True
                    # out_edges already appended; keep it
        # pool validation
        pool_name=edge.get_binding('pool', False)
        if pool_name!="":
            if pool_name not in self.state.pools:
                raise SemanticNoContext(filepath, next_line, f"unknown pool name '{pool_name}'")
            edge.pool=self.state.pools[pool_name]
        # dyndep validation
        dyndep_str=edge.get_binding('dyndep', False)
        if dyndep_str!="":
            canon=canonicalize_path(dyndep_str)
            edge.dyndep_path=canon
            found=None
            for inp in edge.all_inputs:
                if inp.path==canon:
                    found=inp; break
            if found is None:
                raise SemanticNoContext(filepath, next_line, f"dyndep '{dyndep_str}' is not an input")
            edge.dyndep_node=found
            # register group
            grp=self.state.dyndep_groups.setdefault(found, [])
            if edge not in grp: grp.append(edge)
        return idx

def parse_version_numbers(value):
    # sscanf "%d.%d" like
    s=value.strip()
    # major
    m=re.match(r'^([+-]?\d+)', s)
    if not m:
        return (0,0)
    major=int(m.group(1))
    rest=s[m.end():]
    minor=0
    if rest.startswith('.'):
        m2=re.match(r'^\.([+-]?\d+)', rest)
        if m2:
            minor=int(m2.group(1))
    return (major, minor)

class LineCursor:
    def __init__(self, parser, filename, line_no, text, pos, scope):
        self.parser=parser; self.filename=filename; self.line_no=line_no; self.text=text; self.pos=pos; self.scope=scope
    def skip_spaces(self):
        while self.pos < len(self.text) and self.text[self.pos]==' ':
            self.pos+=1
        # also tabs as spaces for some contexts
        while self.pos < len(self.text) and self.text[self.pos]=='\t':
            self.pos+=1
    def at_end(self):
        return self.pos>=len(self.text)
    def peek(self):
        return self.text[self.pos] if self.pos < len(self.text) else ''
    def consume(self, n):
        self.pos+=n
    def read_pipe(self):
        # assume peek == '|'
        start=self.pos
        self.pos+=1
        if self.pos < len(self.text) and self.text[self.pos]=='|':
            self.pos+=1; return 'order'
        if self.pos < len(self.text) and self.text[self.pos]=='@':
            self.pos+=1; return 'validation'
        return 'implicit'
    def read_path_eval(self):
        # Parse an EvalString token until space, colon, pipe.
        start=self.pos
        parts=[]; lit=[]
        def flush():
            if lit:
                parts.append((False, ''.join(lit))); lit.clear()
        while self.pos < len(self.text):
            ch=self.text[self.pos]
            if ch in (' ', '\t', ':', '|'):
                break
            if ch=='$':
                dollar=self.pos
                if self.pos+1>=len(self.text):
                    raise ParseErrorInfo(self.filename, self.line_no, "bad $-escape (literal $ must be written as $$)", self.text, dollar)
                nxt=self.text[self.pos+1]
                if nxt=='$':
                    lit.append('$'); self.pos+=2; continue
                if nxt==' ':
                    lit.append(' '); self.pos+=2; continue
                if nxt==':':
                    lit.append(':'); self.pos+=2; continue
                if nxt=='^':
                    if not self.parser.shared.get('allow_caret'):
                        raise ParseErrorInfo(self.filename, self.line_no, "using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14", self.text, dollar)
                    lit.append('\n'); self.pos+=2; continue
                if nxt=='{':
                    end=self.text.find('}', self.pos+2)
                    if end==-1:
                        raise ParseErrorInfo(self.filename, self.line_no, "bad $-escape (literal $ must be written as $$)", self.text, dollar)
                    varname=self.text[self.pos+2:end]
                    flush(); parts.append((True, varname)); self.pos=end+1; continue
                if nxt in VAR_CHARS:
                    j=self.pos+1
                    while j < len(self.text) and self.text[j] in VAR_CHARS:
                        j+=1
                    varname=self.text[self.pos+1:j]
                    flush(); parts.append((True, varname)); self.pos=j; continue
                raise ParseErrorInfo(self.filename, self.line_no, "bad $-escape (literal $ must be written as $$)", self.text, dollar)
            else:
                lit.append(ch); self.pos+=1
        flush()
        delim=None
        if self.pos < len(self.text):
            delim=self.text[self.pos]
        return EvalString(parts), delim
    def read_paths_until_end(self):
        res=[]
        while True:
            self.skip_spaces()
            if self.at_end():
                break
            if self.peek()=='|':
                # default statements don't support pipes; treat as path? Ninja default parse loops ReadPath which will stop at pipe? Actually path token for '|' would be empty?
                # Break? We'll treat pipe as token start causing empty path error later by caller.
                break
            start=self.pos
            ev, delim = self.read_path_eval()
            res.append((ev, start))
        return res

