class FileLines:
    def __init__(self, filename, content):
        self.filename=filename
        self.content=content
        # physical lines without trailing \n handling like splitlines (removes \r)
        # Use split on \n, strip trailing \r from each.
        raw_lines = content.split('\n')
        # If content ends with \n, split gives final ''
        self.physical=[]
        for idx, rl in enumerate(raw_lines):
            if rl.endswith('\r'):
                rl=rl[:-1]
            self.physical.append(rl)
        # If content ends with \n, last element is sentinel after final newline; we will not treat it as a line.
        self.ends_with_newline = content.endswith('\n') or content==""
        if self.ends_with_newline and self.physical and self.physical[-1]=='':
            # drop trailing sentinel (EOF position will be len(physical))
            # Keep count for EOF line: number of lines = len(raw_lines) (??)
            self.physical = self.physical[:-1]
        self.total_lines_for_eof = self.content.count('\n')+1 if self.content else 1
        # Build logical lines joining $ continuation
        self.logical=[]  # list of (line_no, text)
        i=0
        while i < len(self.physical):
            start_line=i+1
            text=self.physical[i]
            # join continuations: while text ends with a single $ (continuation)
            while self._ends_with_continuation(text) and i+1 < len(self.physical):
                text=text[:-1]  # remove trailing $
                i+=1
                nxt=self.physical[i]
                # strip leading spaces/tabs
                nxt=nxt.lstrip(' \t')
                text=text+nxt
            # If trailing $ continuation at EOF (no next line), keep $ removed? It will be handled as error later.
            self.logical.append((start_line, text))
            i+=1
    def _ends_with_continuation(self, s):
        if not s.endswith('$'):
            return False
        # Scan to determine if final $ is a bare $ continuation vs $$ or $var etc.
        i=0
        last_dollar=-1
        while i < len(s):
            if s[i]=='$':
                if i+1>=len(s):
                    return True
                nxt=s[i+1]
                if nxt=='$':
                    i+=2; continue
                if nxt=='{':
                    end=s.find('}', i+2)
                    if end==-1:
                        return False
                    i=end+1; continue
                if nxt in VAR_CHARS:
                    j=i+1
                    while j<len(s) and s[j] in VAR_CHARS:
                        j+=1
                    i=j; continue
                # $ space, $:, $^ etc consume 2
                i+=2; continue
            else:
                i+=1
        return False

class Parser:
    def __init__(self, state, shared):
        self.state=state
        self.shared=shared  # allow_caret etc, plus metrics parse count
    # Main entry for a file
    def parse_file(self, filepath, scope, is_top=False):
        # filepath as given (relative to cwd)
        try:
            with open(filepath, 'r', encoding='utf-8', errors='surrogateescape', newline='') as f:
                content=f.read()
        except OSError as e:
            # caller handles differences; raise raw
            raise
        # metrics
        self.shared['parse_count']=self.shared.get('parse_count',0)+1
        start=time.perf_counter_ns()
        try:
            self._parse_content(filepath, content, scope)
        finally:
            self.shared['parse_time_ns']=self.shared.get('parse_time_ns',0)+(time.perf_counter_ns()-start)
        # EOF without newline check
        if content and not content.endswith('\n'):
            # Determine last line
            lines=content.split('\n')
            last=lines[-1]
            last_lineno=len(lines)
            if last.lstrip(' \t').startswith('#'):
                raise ParseErrorInfo(filepath, last_lineno, "lexing error", None, None)
            else:
                # unexpected EOF with caret at end of last line
                raise ParseErrorInfo(filepath, last_lineno, "unexpected EOF", last, len(last))
    def _parse_content(self, filepath, content, scope):
        fl=FileLines(filepath, content)
        self._cur_file=filepath
        self._cur_fl=fl
        idx=0
        logical=fl.logical
        def next_token_line(from_idx):
            j=from_idx
            while j < len(logical):
                ln, txt = logical[j]
                if txt.strip()=="" or txt.lstrip(' \t').startswith('#'):
                    j+=1; continue
                return ln
            return fl.total_lines_for_eof
        # helper closures captured via attributes for nested methods
        self._logical=logical
        self._fl=fl
        while idx < len(logical):
            line_no, text = logical[idx]
            idx+=1
            if text.strip()=="":
                continue
            if text.lstrip(' \t').startswith('#'):
                continue
            if text[0] in (' ', '\t'):
                # tab at top level: if it starts with tab, ninja reports tabs not allowed in some contexts,
                # but generic unexpected indent is common.
                if text[0]=='\t' and text.lstrip(' \t').startswith('#'):
                    continue
                raise ParseErrorInfo(filepath, line_no, "unexpected indent", None, None)
            # statement
            # dispatch: parse bindings needs to access idx, so implement inline here with functions using closure variable
            # We implement statement handling in _parse_statement returning new idx
            idx = self._parse_statement(filepath, fl, logical, idx, line_no, text, scope, next_token_line)
    def _parse_statement(self, filepath, fl, logical, idx, line_no, text, scope, next_token_line_fn):
        # returns new idx
        # read first word
        # Identify first token end
        pos=0
        # first chars identifier
        start=0
        while pos < len(text) and text[pos] not in (' ', '\t', '='):
            pos+=1
        first=text[start:pos]
        # Keywords require exact and separator space (or end)
        keyword=None
        if first in ('rule','build','pool','default','include','subninja'):
            # ensure that first is token separated: if text is like 'buildX', first would be buildX not keyword
            keyword=first
        if keyword=='rule':
            return self._parse_rule(filepath, fl, logical, idx, line_no, text, scope, next_token_line_fn)
        elif keyword=='build':
            return self._parse_build(filepath, fl, logical, idx, line_no, text, scope, next_token_line_fn)
        elif keyword=='pool':
            return self._parse_pool(filepath, fl, logical, idx, line_no, text, scope, next_token_line_fn)
        elif keyword=='default':
            return self._parse_default(filepath, fl, logical, idx, line_no, text, scope)
        elif keyword in ('include','subninja'):
            return self._parse_include(filepath, fl, logical, idx, line_no, text, scope, keyword=='subninja')
        else:
            # variable assignment
            self._parse_var_assign(filepath, line_no, text, scope)
            return idx
    # ---------- helpers for line parsing ----------
    def _read_identifier(self, text, pos):
        start=pos
        while pos < len(text) and (text[pos].isalnum() or text[pos] in '_-.'):
            # isalnum for unicode; restrict ascii somewhat
            if ord(text[pos])>127 and not text[pos].isalnum():
                break
            pos+=1
        return text[start:pos], start, pos
    def _skip_spaces(self, text, pos):
        while pos < len(text) and text[pos]==' ':
            pos+=1
        return pos
    def _expect_newline(self, filepath, line_no, text, pos):
        pos=self._skip_spaces(text, pos)
        if pos >= len(text):
            return
        # there's extra token
        ch=text[pos]
        if ch.isalnum() or ch in '_-.':
            raise ParseErrorInfo(filepath, line_no, "expected newline, got identifier", text, pos)
        elif ch==':':
            raise ParseErrorInfo(filepath, line_no, "expected newline, got ':'", text, pos)
        elif ch=='|':
            raise ParseErrorInfo(filepath, line_no, "expected newline, got '|'", text, pos)
        elif ch in (' ', '\t'):
            # indent token? Ninja uses indent for token following? If it is a tab/space leading ... Actually after skipping spaces pos shouldn't be space.
            raise ParseErrorInfo(filepath, line_no, "expected newline, got indent", None, None)
        else:
            raise ParseErrorInfo(filepath, line_no, "expected newline, got identifier", text, pos)
    def _parse_binding_line(self, filepath, line_no, text):
        # text is indented line. Returns (name, value_evalstring, value_offset_pos_for_errors, raw_line)
        pos=0
        while pos < len(text) and text[pos]==' ':
            pos+=1
        # name
        name, name_start, pos = self._read_identifier(text, pos)
        if not name:
            # e.g. indented line begins with something else
            # Try to produce expected '=', got ...
            raise ParseErrorInfo(filepath, line_no, "expected '=', got lexing error", text, pos)
        pos2=self._skip_spaces(text, pos)
        if pos2>=len(text):
            raise ParseErrorInfo(filepath, line_no, "expected '=', got newline", text, pos2)
        if text[pos2]=='\t':
            raise ParseErrorInfo(filepath, line_no, "expected '=', got lexing error", text, pos2)
        if text[pos2]!='=':
            # identifier or other
            if text[pos2].isalnum() or text[pos2] in '_-.':
                raise ParseErrorInfo(filepath, line_no, "expected '=', got identifier", text, pos2)
            else:
                raise ParseErrorInfo(filepath, line_no, "expected '=', got lexing error", text, pos2)
        pos=pos2+1
        # skip leading spaces in value
        while pos < len(text) and text[pos] in (' ', '\t'):
            pos+=1
        value_text=text[pos:]
        ev=parse_eval_string(value_text, pos, filepath, line_no, text, self.shared)
        return name, ev, pos
    def _parse_bindings_block(self, filepath, fl, logical, idx, allowed_names, block_kind):
        # returns dict name->EvalString (for rule/pool) or evaluated string (handled by caller), and new idx.
        # This method returns raw eval dict and also order.
        bindings=[]
        while idx < len(logical):
            line_no, text = logical[idx]
            if text.strip()=="":
                break
            if text.lstrip(' \t').startswith('#'):
                idx+=1; continue
            if not text.startswith(' '):
                break
            # parse binding
            name, ev, vpos = self._parse_binding_line(filepath, line_no, text)
            if allowed_names is not None and name not in allowed_names:
                # error after parsing value, caret at end of line
                raise ParseErrorInfo(filepath, line_no, f"unexpected variable '{name}'", text, len(text))
            bindings.append((name, ev, line_no, text))
            idx+=1
        return bindings, idx
    def _next_line_no(self, logical, idx, fl):
        j=idx
        while j < len(logical):
            ln, txt=logical[j]
            if txt.strip()=="" or txt.lstrip(' \t').startswith('#'):
                j+=1; continue
            return ln
        return fl.total_lines_for_eof
    # ---------- statement parsers ----------
    def _parse_rule(self, filepath, fl, logical, idx, line_no, text, scope, next_token_line_fn):
        pos=len('rule')
        pos=self._skip_spaces(text, pos)
        name_start=pos
        name, _, pos = self._read_identifier(text, pos)
        if not name:
            raise ParseErrorInfo(filepath, line_no, "expected rule name", text, name_start)
        # expect newline (extra)
        # Note: if next char is something like $ etc, _expect will treat...
        self._expect_newline(filepath, line_no, text, pos)
        allowed={'command','depfile','deps','description','dyndep','generator','msvc_deps_prefix','pool','restat','rspfile','rspfile_content'}
        bindings_list, idx = self._parse_bindings_block(filepath, fl, logical, idx, allowed, 'rule')
        rule=Rule(name)
        for nm, ev, ln, txt in bindings_list:
            rule.bindings[nm]=ev
        if 'command' not in rule.bindings:
            raise SemanticNoContext(filepath, self._next_line_no(logical, idx, fl), "expected 'command =' line")
        if name in scope.rules:
            raise ParseErrorInfo(filepath, line_no, f"duplicate rule '{name}'", text, name_start)
        scope.rules[name]=rule
        return idx
    def _parse_pool(self, filepath, fl, logical, idx, line_no, text, scope, next_token_line_fn):
        pos=len('pool')
        pos=self._skip_spaces(text, pos)
        name_start=pos
        name, _, pos = self._read_identifier(text, pos)
        if not name:
            raise ParseErrorInfo(filepath, line_no, "expected pool name", text, name_start)
        self._expect_newline(filepath, line_no, text, pos)
        allowed={'depth'}
        bindings_list, idx = self._parse_bindings_block(filepath, fl, logical, idx, allowed, 'pool')
        # find depth
        depth_ev=None; depth_line=None; depth_text=None
        for nm, ev, ln, txt in bindings_list:
            if nm=='depth':
                depth_ev=ev; depth_line=ln; depth_text=txt
        if depth_ev is None:
            raise SemanticNoContext(filepath, self._next_line_no(logical, idx, fl), "expected 'depth =' line")
        depth_str=depth_ev.evaluate(lambda vn: scope.lookup_var(vn))
        # parse int like atoi / strtol
        depth_val=self._parse_pool_depth(depth_str, filepath, depth_line, depth_text)
        if name in self.state.pools:
            raise ParseErrorInfo(filepath, line_no, f"duplicate pool '{name}'", text, name_start)
        self.state.pools[name]=Pool(name, depth_val)
        return idx
    def _parse_pool_depth(self, s, filepath, line_no, line_text):
        # atoi-like: skip leading spaces, sign, digits; if no digits ->0
        t=s.lstrip(' \t')
        sign=1; i=0
        if i < len(t) and t[i] in '+-':
            if t[i]=='-': sign=-1
            i+=1
        start=i
        val=0; overflow=False
        while i < len(t) and t[i].isdigit():
            val=val*10+(ord(t[i])-48)
            if val> 2**31:
                overflow=True
            i+=1
        if start==i:
            return 0
        val=val*sign
        if val <0 or val>2147483647:
            raise ParseErrorInfo(filepath, line_no, "invalid pool depth", line_text, len(line_text) if line_text else 0)
        return val
    def _parse_var_assign(self, filepath, line_no, text, scope):
        # identifier
        pos=0
        # Check first char: if tab or weird ??? Caller ensured not indented.
        name, name_start, pos = self._read_identifier(text, pos)
        if not name:
            # char at 0 is something else
            raise ParseErrorInfo(filepath, line_no, "expected '=', got lexing error", text, 0)
