        pos_skip=self._skip_spaces(text, pos)
        if pos_skip < len(text) and text[pos_skip]=='\t':
            raise ParseErrorInfo(filepath, line_no, "expected '=', got lexing error", text, pos_skip)
        pos=pos_skip
        if pos>=len(text):
            raise ParseErrorInfo(filepath, line_no, "expected '=', got newline", text, pos)
        if text[pos]!='=':
            if text[pos].isalnum() or text[pos] in '_-.':
                raise ParseErrorInfo(filepath, line_no, "expected '=', got identifier", text, pos)
            else:
                raise ParseErrorInfo(filepath, line_no, "expected '=', got lexing error", text, pos)
        pos+=1
        while pos < len(text) and text[pos] in (' ', '\t'):
            pos+=1
