            raise NinjaFail(stderr_text=fatal_msg(f"ninja version ({VERSION}) incompatible with build file ninja_required_version version ({value})."), code=1)
        if major < VERSION_MAJOR:
            warn_msg(f"ninja executable version ({VERSION}) greater than build file ninja_required_version ({value}); versions may be incompatible.")
