    def _parse_default(self, filepath, fl, logical, idx, line_no, text, scope):
        pos=len('default')
        cursor=LineCursor(self, filepath, line_no, text, pos, scope)
        paths=cursor.read_paths_until_end()
        if not paths:
            # expected target name at position after 'default'
            raise ParseErrorInfo(filepath, line_no, "expected target name", text, pos+1 if pos < len(text) else len(text))
        # paths is list of (evalstr, startpos)
        for ev, startpos in paths:
            val=ev.evaluate(lambda vn: scope.lookup_var(vn))
            if val=="":
                raise ParseErrorInfo(filepath, line_no, "empty path", text, startpos)
            canon=canonicalize_path(val)
            node=self.state.lookup_node(canon)
