        keyword='subninja' if is_subninja else 'include'
        pos=len(keyword)
        cursor=LineCursor(self, filepath, line_no, text, pos, scope)
        cursor.skip_spaces()
        startpos=cursor.pos
        if cursor.at_end():
            raise ParseErrorInfo(filepath, line_no, "expected path", text, startpos)
