        try:
            self.parse_file(val, new_scope)
        except OSError as e:
            errname=strerror_from_errno(e.errno) if e.errno else str(e)
            raise ParseErrorInfo(filepath, line_no, f"loading '{val}': {errname}", text, after_pos)
        except ParseErrorInfo:
            raise
        except SemanticNoContext:
            raise
