    def _parse_build(self, filepath, fl, logical, idx, line_no, text, scope, next_token_line_fn):
        pos=len('build')
        cursor=LineCursor(self, filepath, line_no, text, pos, scope)
        # outputs
        outputs=[]; implicit_outs=[]
        stage='explicit'
        first_token=True
        while True:
            cursor.skip_spaces()
            if cursor.at_end():
                raise ParseErrorInfo(filepath, line_no, "expected ':', got newline ($ also escapes ':')", text, cursor.pos)
            ch=cursor.peek()
            if ch==':':
                if first_token:
                    raise ParseErrorInfo(filepath, line_no, "expected path", text, cursor.pos)
                cursor.consume(1); break
            if ch=='|':
                pipe_start=cursor.pos
                ptype=cursor.read_pipe()
                if ptype!='implicit':
                    # In outputs, only single | allowed. Treat || or |@ as error ?
