def parse_version_numbers(value):
    # sscanf "%d.%d" like
    s=value.strip()
    # major
    m=re.match(r'^([+-]?\d+)', s)
    if not m:
        return (0,0)
    major=int(m.group(1))
    rest=s[m.end():]
    minor=0
    if rest.startswith('.'):
        m2=re.match(r'^\.([+-]?\d+)', rest)
        if m2:
            minor=int(m2.group(1))
    return (major, minor)

