                    flush(); parts.append((True, varname)); self.pos=j; continue
                raise ParseErrorInfo(self.filename, self.line_no, "bad $-escape (literal $ must be written as $$)", self.text, dollar)
            else:
                lit.append(ch); self.pos+=1
        flush()
        delim=None
        if self.pos < len(self.text):
            delim=self.text[self.pos]
        return EvalString(parts), delim
    def read_paths_until_end(self):
        res=[]
        while True:
            self.skip_spaces()
            if self.at_end():
                break
            if self.peek()=='|':
                # default statements don't support pipes; treat as path? Ninja default parse loops ReadPath which will stop at pipe? Actually path token for '|' would be empty?
                # Break? We'll treat pipe as token start causing empty path error later by caller.
                break
            start=self.pos
            ev, delim = self.read_path_eval()
            res.append((ev, start))
        return res

