# ---------- Hash for command ----------
def hash_command_bytes(data):
    # FNV-1a 64
    h=14695981039346656037
    p=1099511628211
    mask=(1<<64)-1
    for b in data:
        h ^= b
        h=(h*p)&mask
    return h

