class Jobserver:
    def __init__(self, config):
        self.config=config
        self.mode=None  # None inactive, 'fifo'
        self.read_fd=None; self.write_fd=None
        self.initialized=False
        self.tokens_held=[]  # bytes acquired as extra slots currently available? Managed by builder
    def ensure_init(self):
        if self.initialized:
            return
        self.initialized=True
        if self.config.dry_run: return
        if self.config.explicit_parallelism: return
        mf=os.environ.get("MAKEFLAGS")
        if mf is None: return
        # token parsing
        mode=None; value=None
        # split tokens respecting backslash escapes for spaces
        tokens=[]; cur=[]; i=0
        while i < len(mf):
            ch=mf[i]
            if ch=='\\' and i+1 < len(mf):
                cur.append(ch); cur.append(mf[i+1]); i+=2; continue
            if ch in (' ','\t'):
                if cur: tokens.append(''.join(cur)); cur=[]
                i+=1; continue
            cur.append(ch); i+=1
        if cur: tokens.append(''.join(cur))
        for tok in tokens:
            for prefix in ('--jobserver-auth=','--jobserver-fds='):
                if tok.startswith(prefix):
                    value=tok[len(prefix):]
                    # determine mode based on this token, last wins
                    if value.startswith('fifo:'):
                        mode='fifo'
                    elif has_unescaped_comma(value):
                        mode='pipe'
                    else:
                        mode='semaphore'
                    break
        if mode is None:
            return
        if mode=='pipe':
            err_str(f"ninja: warning: Ignoring jobserver: Pipe-based protocol is not supported! [{mf}]\n")
            return
        if mode=='semaphore':
            err_str(f"ninja: warning: Ignoring jobserver: Semaphore mode is not supported on Posix! [{mf}]\n")
            return
        # fifo
        if self.config.verbosity!=QUIET:
            out_str(f"ninja: Jobserver mode detected: {mf}\n")
        # find last fifo value
        fifo_path=None
        for tok in tokens:
            for prefix in ('--jobserver-auth=','--jobserver-fds='):
                if tok.startswith(prefix) and tok[len(prefix):].startswith('fifo:'):
