        mode=None; value=None
        # split tokens respecting backslash escapes for spaces
        tokens=[]; cur=[]; i=0
        while i < len(mf):
            ch=mf[i]
            if ch=='\\' and i+1 < len(mf):
                cur.append(ch); cur.append(mf[i+1]); i+=2; continue
            if ch in (' ','\t'):
                if cur: tokens.append(''.join(cur)); cur=[]
                i+=1; continue
            cur.append(ch); i+=1
