            err_str(f"ninja: warning: Ignoring jobserver: Pipe-based protocol is not supported! [{mf}]\n")
            return
        if mode=='semaphore':
            err_str(f"ninja: warning: Ignoring jobserver: Semaphore mode is not supported on Posix! [{mf}]\n")
            return
