def render_browse_page(state, target, ninja_cmd, build_f):
    # Mimic original page template somewhat. It uses ninja -t query parsing; we use our state directly.
    import html
    header="""<!DOCTYPE html>
<style>
body {
    font-family: sans;
    font-size: 0.8em;
    margin: 4ex;
}
h1 {
    font-weight: normal;
    font-size: 140%;
    text-align: center;
    margin: 0;
}
h2 {
    font-weight: normal;
    font-size: 120%;
}
tt {
    font-family: WebKitHack, monospace;
    white-space: nowrap;
}
.filelist {
  -webkit-columns: auto 2;
}
</style>
"""
    if target=="":
        return header+f"<h1><tt>ninja: error: empty path\n</tt></h1>\n"
    node=state.lookup_node(canonicalize_path(target)) if target else None
    if node is None:
