        if sug: msg+=f", did you mean '{html.escape(sug)}'?"
        msg=msg.replace("'", "&#x27;")
        return header+f"<h1><tt>{msg}\n</tt></h1>\n"
    parts=[header]
    parts.append(f"<h1><tt>{html.escape(node.path)}</tt></h1>\n")
    e=node.in_edge
    if e:
        parts.append(f"<h2>target is built using rule <tt>{html.escape(e.rule.name)}</tt> of</h2>\n")
        parts.append("<div class=filelist>\n")
        for inp in e.all_inputs:
            parts.append(f'<tt><a href="?{html.escape(inp.path)}">{html.escape(inp.path)}</a></tt><br>\n')
        parts.append("</div>\n")
    if node.out_edges:
        parts.append("<h2>target is used by</h2>\n")
        parts.append("<div class=filelist>\n")
        seen=set()
        for oe in node.out_edges:
            for o in oe.all_outputs:
                if o.path not in seen:
                    seen.add(o.path)
                    parts.append(f'<tt><a href="?{html.escape(o.path)}">{html.escape(o.path)}</a></tt><br>\n')
        parts.append("</div>\n")
    return ''.join(parts)

