def make_table(poly_rev):
    table=[]
    for i in range(256):
        crc=i
        for _ in range(8):
            crc = (crc>>1) ^ (poly_rev if (crc & 1) else 0)
        table.append(crc)
    return table
def crc64(data, poly_rev, init, xorout):
    table=make_table(poly_rev); crc=init
