k0=0xc3a5c85c97cb3127; k1=0xb492b66fbe98f273; k2=0x9ae16a3b2f90404f
def rot(v,s):
    return ((v>>s)|(v<<(64-s)))&MASK if s else v
def shiftmix(v): return (v ^ (v>>47))&MASK
def hashlen16(u,v,mul):
    a=((u^v)*mul)&MASK; a ^= a>>47; b=((v^a)*mul)&MASK; b ^= b>>47; b=(b*mul)&MASK; return b
def fetch64(p,i): return struct.unpack_from('<Q',p,i)[0]
def fetch32(p,i): return struct.unpack_from('<I',p,i)[0]
def city64(s):
